)

# Find the nation with the greatest number of languages
nation_with_most_languages = countries.WHERE(
    HAS(countrylanguages) == 1
).CALCULATE(
    country_name=name,
    language_count=COUNT(countrylanguages)
).ORDER_BY(language_count.DESC(), country_name.ASC()).CALCULATE(
    country_name=country_name
)

# Find the minimum surface area among European countries and use it to filter all countries
result = world_1.CALCULATE(
    min_europe_surface_area = MIN(countries.WHERE(continent == "Europe").surfacearea)
).countries.WHERE(
    surfacearea > min_europe_surface_area
).CALCULATE(
    country_name = name
)

# Filter countries founded before 1930 and count distinct official languages
countries_before_1930_official_langs = countries.WHERE(
    indepyear < 1930
).countrylanguages.WHERE(
    isofficial == "T"
)

result = world_1.CALCULATE(
    distinct_official_languages=NDISTINCT(countries_before_1930_official_langs.language)
)

# Find Asian countries with population larger than any African country
asian_countries_larger_than_africa = world_1.CALCULATE(
    min_african_population = MIN(countries.WHERE(continent == "Africa").population)
).countries.WHERE(
