    staff_name=staff_name,
    assignment_duration=MIN(staff_department_assignment.CALCULATE(
        duration=DATEDIFF("days", date_assigned_from, DEFAULT_TO(date_assigned_to, DATETIME('now')))
    ).duration)
).TOP_K(1, by=assignment_duration.ASC())

# Find suppliers with average amount purchased above 50000 or below 30000
qualifying_suppliers = supplier.WHERE(
    HAS(product_supplier) == 1
).CALCULATE(
    supplier_id=supplier_id,
    avg_amount_purchased=AVG(product_supplier.total_amount_purchased)
).WHERE(
    (avg_amount_purchased > 50000) | (avg_amount_purchased < 30000)
).CALCULATE(
    supplier_id=supplier_id
)

# Find staff whose assignment date is earlier than any clerical staff
result = department_store.CALCULATE(
    latest_clerical_date = MAX(staff_department_assignment.WHERE(
        job_title_code == "Clerical Staff"
    ).date_assigned_to)
).staff_department_assignment.WHERE(
    date_assigned_to < latest_clerical_date
).CALCULATE(
    staff_id = staff_id
)

products_with_multiple_customers = product.WHERE(
    HAS(order_item) == 1
).CALCULATE(
    product_name=product_name,
    distinct_customers=NDISTINCT(order_item.customer_order.customer_id)
).WHERE(
    distinct_customers >= 2
).CALCULATE(
    product_name=product_name
)

# Count distinct locations where things with 'Unsatisfied' service details have been located
distinct_locations_count = local_govt_and_lot.CALCULATE(
    distinct_location_count = NDISTINCT(thing.WHERE(
        service_details == 'Unsatisfied'
    ).timed_locations_of_thing.location_code)
)

# Calculate the average product price across all products
avg_price = cre_Drama_Workshop_Groups.CALCULATE(
    average_price=AVG(product.product_price)
)

# Filter products with price higher than average and get distinct product names
products_above_average = avg_price.product.WHERE(
    product_price > average_price
).CALCULATE(
    product_name=product_name
).PARTITION(name="distinct_products", by=product_name).CALCULATE(
    product_name=product_name
)

# Calculate the average product price and filter products above average
above_average_products = cre_Drama_Workshop_Groups.CALCULATE(
    avg_product_price=AVG(product.product_price)
).product.WHERE(
    product_price > avg_product_price
).CALCULATE(
    product_name=product_name
).PARTITION(name="distinct_products", by=product_name).CALCULATE(
    product_name=product_name
)

# Find order details for products with price above 2000
order_details_high_price = order_item.WHERE(
    product.product_price > "2000"
).CALCULATE(
    other_item_details=other_item_details
)

alaska_drama_groups = drama_workshop_group.WHERE(
    address.state_county == "Alaska"
).CALCULATE(
    email_address=store_email_address
)

feliciaberg_groups = drama_workshop_group.WHERE(
    address.city_town == "Feliciaberg"
).CALCULATE(
    group_name=store_name
)

# Find cities where at least one customer lives but no performer lives
cities_with_customers_no_performers = address.WHERE(
    (HAS(customer) == 1) & (HASNOT(performer) == 1)
).CALCULATE(
    city_town=city_town
).PARTITION(name="cities", by=city_town).CALCULATE(
    city_town=city_town
)

# Get order dates for orders with items having price higher than 1000
order_dates_high_price = customer_order.order_item.WHERE(
    product.product_price > 1000
).CALCULATE(
    order_date=customer_order.order_date
)

flash_musicians_count = song.WHERE(title == "Flash").CALCULATE(
    count_musicians = COUNT(performances)
)

# Find cities that have at least one customer but no performer
cities_with_customers_no_performers = address.WHERE(
    HAS(customer) == 1
).WHERE(
    HASNOT(performer) == 1
).CALCULATE(
    city_name = city_town
)

# Filter manufacturers with headquarters in Tokyo or Taiwan and sum their revenue
total_revenue_result = manufactory_1.CALCULATE(
    total_revenue=SUM(manufacturer.WHERE(
        (headquarter == "Tokyo") | (headquarter == "Taiwan")
    ).revenue)
)

# Calculate the average revenue across all manufacturers at graph level
avg_revenue_info = manufactory_1.CALCULATE(
    avg_revenue=AVG(manufacturer.revenue)
)

# Filter manufacturers with revenue greater than average and get their names
high_revenue_manufacturers = avg_revenue_info.manufacturer.WHERE(
    revenue > avg_revenue
).CALCULATE(
    name=name
)

# Find distinct first names of students with vice president votes and city code not PIT
distinct_first_names = students.WHERE(
    (city_code != "PIT") & 
    (HAS(voting_records.WHERE(vice_president_vote != None)) == 1)
).CALCULATE(
    first_name=fname
).PARTITION(
    name="names", by=first_name
).CALCULATE(
    first_name=first_name
)

# Calculate the average capacity across all stadiums at the graph level
# Then filter stadiums with capacity below average and return their names
below_average_stadiums = swimming.CALCULATE(
    avg_capacity = AVG(stadiums.capacity)
).stadiums.WHERE(
    capacity < avg_capacity
).CALCULATE(
    stadium_name = name
)

countries_with_qualified_managers = managers.WHERE(
    (age > "50") | (age < "46")
).CALCULATE(country=country)
